#!/bin/bash -p
# SPDX-License-Identifier: MIT
# Copyright (c) 2026 Brighton Sikarskie
# SHEBANG-SECURITY: -p blocks BASH_ENV and exported-function startup injection.
#
# provision_doxygen.sh -- resolve the project-pinned doxygen binary.
#
# The Doxygen HTML templates in docs/doxygen_theme/ (header.html) and the
# vendored doxygen-awesome theme are only valid for ONE doxygen version:
# templates generated by a newer doxygen leave placeholders like $mermaidjs
# unexpanded when rendered by an older one, and the theme CSS tracks the
# markup of specific doxygen releases. Every docs build (local `just docs::build`,
# the docs-publish workflow, the firmware.yml doxygen warning gate) must
# therefore use the exact same doxygen release. This script pins it.
#
# Resolution order:
#   1. A previously provisioned copy under build/tools/ (no network).
#   2. A `doxygen` already on PATH with the exact pinned version.
#   3. Download of the official release binary from the doxygen GitHub
#      releases page, verified against a pinned sha256, into build/tools/.
#
# Prints the absolute path of the doxygen binary on stdout; all progress
# and error text goes to stderr. Intended usage:
#
#   DOXYGEN_BIN="$(/bin/bash -p scripts/builders/provision_doxygen.sh)"
#
# When bumping the pin: update PINNED_VERSION and the three sha256 values
# below, re-vendor a doxygen-awesome release that supports the new version,
# and regenerate docs/doxygen_theme/header.html (see docs/DOCS.md).

if [[ "$-" == *p* ]]; then
  unset -v BASH_ENV ENV
  declare -a ra8_startup_env_unset=()
  _ra8_startup_refuse() {
    printf 'error: privileged startup %s\n' "$1" >&2
    exit 1
  }
  ra8_startup_env_done_count=0
  while IFS= read -r -d '' ra8_startup_env_row; do
    ra8_startup_env_name="${ra8_startup_env_row%%=*}"
    case "$ra8_startup_env_name" in
      RA8_STARTUP_ENV_DONE)
        ra8_startup_env_done_count=$((ra8_startup_env_done_count + 1))
        ;;
      BASH_FUNC_*%% | BASH_FUNC_*'()') ra8_startup_env_unset+=(-u "$ra8_startup_env_name") ;;
    esac
  done < <(
    /usr/bin/env -u RA8_STARTUP_ENV_DONE -0 &&
      /usr/bin/printf 'RA8_STARTUP_ENV_DONE=1\0'
  )
  ((ra8_startup_env_done_count == 1)) && [[ "$ra8_startup_env_name" == RA8_STARTUP_ENV_DONE ]] || _ra8_startup_refuse 'environment enumeration was incomplete'
  if ((${#ra8_startup_env_unset[@]})); then
    [[ -z "${RA8_STARTUP_ENV_SCRUBBED-}" ]] || _ra8_startup_refuse 'scrub did not converge'
    ra8_startup_reentry="$0"
    [[ "$ra8_startup_reentry" == */* ]] || _ra8_startup_refuse 'requires a script path'
    if [[ "$ra8_startup_reentry" != /* ]]; then
      ra8_startup_reentry="$PWD/$ra8_startup_reentry"
    fi
    ra8_startup_check="$ra8_startup_reentry"
    while [[ "$ra8_startup_check" != "/" ]]; do
      [[ ! -L "$ra8_startup_check" ]] || _ra8_startup_refuse 'refuses a symlinked path'
      ra8_startup_parent="${ra8_startup_check%/*}"
      [[ -n "$ra8_startup_parent" ]] || ra8_startup_parent="/"
      [[ "$ra8_startup_parent" != "$ra8_startup_check" ]] ||
        _ra8_startup_refuse 'cannot validate its script path'
      ra8_startup_check="$ra8_startup_parent"
    done
    [[ -f "$ra8_startup_reentry" ]] || _ra8_startup_refuse 'refuses a non-regular path'
    if ! exec /usr/bin/env "${ra8_startup_env_unset[@]}" -u BASH_ENV -u ENV \
      -u RA8_STARTUP_ENV_DONE RA8_STARTUP_ENV_SCRUBBED=1 \
      /bin/bash -p -- "$ra8_startup_reentry" "$@"; then
      _ra8_startup_refuse 'could not enter sanitized process'
    fi
  fi
  unset -v ra8_startup_check ra8_startup_env_done_count
  unset -v ra8_startup_env_name ra8_startup_env_row
  unset -v ra8_startup_env_unset ra8_startup_parent ra8_startup_reentry
  unset -v RA8_STARTUP_ENV_DONE
  unset -v RA8_STARTUP_ENV_SCRUBBED
  unset -f _ra8_startup_refuse

  set -euo pipefail

  SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  ROOT_DIR="$(cd "${SCRIPT_DIR}/../.." && pwd)"

  # doxygen-awesome-css v2.4.2 supports doxygen up to 1.16.1, so that is the
  # newest release the published theme is valid for.
  PINNED_VERSION="1.16.1"
  RELEASE_TAG="Release_1_16_1"
  BASE_URL="https://github.com/doxygen/doxygen/releases/download/${RELEASE_TAG}"

  # sha256 of the official release artifacts (from the doxygen GitHub release).
  SHA256_LINUX_X64="a56f885d37e3aae08a99f638d17bbb381224c03a878d9e2dda4f9fa4baf1d8bd"
  SHA256_MAC_ARM64="f75d4e7253ad959d691cb65b6c3a9bb0c138ce75bce7cef17f5ebf36c7b54bdc"
  SHA256_MAC_X64="1530e5eca05b442e4cdd80a8ad6b22e1bbb3fc14e12b64b07c61de4be48cc5f1"

  # Where the provisioned binary is cached.
  #
  # Default: build/tools/ under the repo. Every ephemeral `just ci` snapshot
  # recreates and then destroys that tree, so under the suite runner the download
  # would repeat every run -- and fail outright with no network. RA8_TOOLS_CACHE
  # points this at a PERSISTENT directory that survives the snapshot: scripts/ci.sh
  # mounts one into the container and exports it for native runs, exactly as the
  # ccache mount lets compiled objects survive (issue #326). It is namespaced by
  # OS + arch so a macOS host and a Linux container that share one host directory
  # never fight over the same doxygen-<version>/ subtree.
  if [[ -n "${RA8_TOOLS_CACHE:-}" ]]; then
    TOOLS_DIR="${RA8_TOOLS_CACHE}/$(uname -s)-$(uname -m)"
  else
    TOOLS_DIR="${ROOT_DIR}/build/tools"
  fi

  log() { echo "provision_doxygen.sh: $*" >&2; }

  # Portable sha256 (Linux: sha256sum, macOS: shasum).
  sha256_of() {
    if command -v sha256sum >/dev/null 2>&1; then
      sha256sum "$1" | awk '{print $1}'
    else
      shasum -a 256 "$1" | awk '{print $1}'
    fi
  }

  # True when the given doxygen binary reports exactly the pinned version.
  # `doxygen --version` prints e.g. "1.16.1 (669aeee...)"; compare field 1.
  is_pinned_version() {
    local reported
    reported="$("$1" --version 2>/dev/null | awk '{print $1}')" || return 1
    [[ "${reported}" == "${PINNED_VERSION}" ]]
  }

  # Pick the official artifact + in-archive binary path for this host.
  OS="$(uname -s)"
  ARCH="$(uname -m)"
  case "${OS}-${ARCH}" in
    Linux-x86_64)
      ARTIFACT="doxygen-${PINNED_VERSION}.linux.bin.tar.gz"
      SHA256="${SHA256_LINUX_X64}"
      BIN_SUBPATH="doxygen-${PINNED_VERSION}/bin/doxygen"
      ;;
    Darwin-arm64)
      ARTIFACT="doxygen-${PINNED_VERSION}-mac-arm.zip"
      SHA256="${SHA256_MAC_ARM64}"
      BIN_SUBPATH="doxygen-${PINNED_VERSION}/doxygen"
      ;;
    Darwin-x86_64)
      ARTIFACT="doxygen-${PINNED_VERSION}-mac-intel.zip"
      SHA256="${SHA256_MAC_X64}"
      BIN_SUBPATH="doxygen-${PINNED_VERSION}/doxygen"
      ;;
    *)
      ARTIFACT=""
      SHA256=""
      BIN_SUBPATH=""
      ;;
  esac

  CACHED_BIN="${TOOLS_DIR}/${BIN_SUBPATH}"

  # 1. Previously provisioned copy.
  if [[ -n "${BIN_SUBPATH}" && -x "${CACHED_BIN}" ]] && is_pinned_version "${CACHED_BIN}"; then
    echo "${CACHED_BIN}"
    exit 0
  fi

  # 2. PATH doxygen with the exact pinned version.
  if command -v doxygen >/dev/null 2>&1 && is_pinned_version "$(command -v doxygen)"; then
    command -v doxygen
    exit 0
  fi

  # 3. Download the official pinned release binary.
  if [[ -z "${ARTIFACT}" ]]; then
    log "ERROR: no official doxygen ${PINNED_VERSION} binary for ${OS}/${ARCH}."
    log "Install doxygen ${PINNED_VERSION} on PATH and re-run."
    exit 1
  fi

  log "doxygen ${PINNED_VERSION} not found -- downloading ${ARTIFACT} ..."
  mkdir -p "${TOOLS_DIR}"
  DL_TMP="$(mktemp -d "${TOOLS_DIR}/doxygen-dl.XXXXXX")"
  trap 'rm -rf "${DL_TMP}"' EXIT

  curl -fL --retry 3 --retry-delay 2 -o "${DL_TMP}/${ARTIFACT}" \
    "${BASE_URL}/${ARTIFACT}" >&2

  ACTUAL_SHA256="$(sha256_of "${DL_TMP}/${ARTIFACT}")"
  if [[ "${ACTUAL_SHA256}" != "${SHA256}" ]]; then
    log "ERROR: sha256 mismatch for ${ARTIFACT}:"
    log "  expected ${SHA256}"
    log "  actual   ${ACTUAL_SHA256}"
    exit 1
  fi

  case "${ARTIFACT}" in
    *.tar.gz) tar -xzf "${DL_TMP}/${ARTIFACT}" -C "${DL_TMP}" ;;
    *.zip) unzip -q "${DL_TMP}/${ARTIFACT}" -d "${DL_TMP}" ;;
  esac

  if [[ ! -x "${DL_TMP}/${BIN_SUBPATH}" ]]; then
    log "ERROR: ${BIN_SUBPATH} not found inside ${ARTIFACT}."
    exit 1
  fi

  # Move into the final cache location atomically-ish: extract fully first,
  # then rename. A concurrent run would at worst re-extract the same bytes.
  DEST_DIR="${TOOLS_DIR}/doxygen-${PINNED_VERSION}"
  rm -rf "${DEST_DIR}"
  mv "${DL_TMP}/doxygen-${PINNED_VERSION}" "${DEST_DIR}"

  if ! is_pinned_version "${CACHED_BIN}"; then
    log "ERROR: provisioned binary at ${CACHED_BIN} failed the version check."
    exit 1
  fi

  log "provisioned doxygen ${PINNED_VERSION} -> ${CACHED_BIN}"
  echo "${CACHED_BIN}"
else
  [[ "$-" == *p* ]]
fi
